use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};
use tokio::task::JoinHandle;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum EvictReason {
    Expired,
    Lru,
    Memory,
}

pub type OnEvict = Arc<dyn Fn(&str, EvictReason) + Send + Sync>;

pub struct CacheConfig {
    pub max_entries: usize,
    pub default_ttl: Duration,
    pub max_memory_bytes: usize,
    pub eviction_check_interval: Duration,
    pub on_evict: Option<OnEvict>,
}

impl Default for CacheConfig {
    fn default() -> Self {
        Self {
            max_entries: 1000,
            default_ttl: Duration::from_millis(60_000),
            max_memory_bytes: 100 * 1024 * 1024,
            eviction_check_interval: Duration::from_millis(5_000),
            on_evict: None,
        }
    }
}

struct Node<V> {
    key: Arc<str>,
    value: V,
    expires_at: Instant,
    size: usize,
    last_accessed: Instant,
    access_count: u64,
    prev: Option<usize>,
    next: Option<usize>,
}

#[derive(Default, Clone, Copy, Debug)]
struct Stats {
    hits: u64,
    misses: u64,
    evictions: u64,
    expirations: u64,
}

#[derive(Clone, Copy, Debug)]
pub struct StatsSnapshot {
    pub hits: u64,
    pub misses: u64,
    pub evictions: u64,
    pub expirations: u64,
    pub size: usize,
    pub memory: usize,
}

struct Inner<V> {
    nodes: Vec<Option<Node<V>>>,
    free: Vec<usize>,
    map: HashMap<Arc<str>, usize>,
    head: Option<usize>, // most-recently used
    tail: Option<usize>, // least-recently used
    current_memory: usize,
    config: CacheConfig,
    stats: Stats,
}

impl<V> Inner<V> {
    fn alloc_node(&mut self, node: Node<V>) -> usize {
        if let Some(idx) = self.free.pop() {
            self.nodes[idx] = Some(node);
            idx
        } else {
            self.nodes.push(Some(node));
            self.nodes.len() - 1
        }
    }

    fn detach(&mut self, idx: usize) {
        let (prev, next) = {
            let n = self.nodes[idx].as_ref().expect("node");
            (n.prev, n.next)
        };
        match prev {
            Some(p) => self.nodes[p].as_mut().expect("prev").next = next,
            None => self.head = next,
        }
        match next {
            Some(n) => self.nodes[n].as_mut().expect("next").prev = prev,
            None => self.tail = prev,
        }
        let n = self.nodes[idx].as_mut().expect("node");
        n.prev = None;
        n.next = None;
    }

    fn push_front(&mut self, idx: usize) {
        let old_head = self.head;
        {
            let n = self.nodes[idx].as_mut().expect("node");
            n.prev = None;
            n.next = old_head;
        }
        if let Some(h) = old_head {
            self.nodes[h].as_mut().expect("old head").prev = Some(idx);
        } else {
            self.tail = Some(idx);
        }
        self.head = Some(idx);
    }

    fn move_to_front(&mut self, idx: usize) {
        if self.head == Some(idx) {
            return;
        }
        self.detach(idx);
        self.push_front(idx);
    }

    fn remove_idx(&mut self, idx: usize, reason: EvictReason) {
        self.detach(idx);
        let node = self.nodes[idx].take().expect("node");
        self.free.push(idx);
        self.current_memory = self.current_memory.saturating_sub(node.size);
        self.map.remove(&node.key);
        match reason {
            EvictReason::Expired => self.stats.expirations += 1,
            _ => self.stats.evictions += 1,
        }
        if let Some(cb) = &self.config.on_evict {
            cb(&node.key, reason);
        }
    }

    fn evict_lru(&mut self, reason: EvictReason) {
        if let Some(t) = self.tail {
            self.remove_idx(t, reason);
        }
    }
}

pub struct LruCache<V> {
    inner: Arc<Mutex<Inner<V>>>,
    eviction_task: Mutex<Option<JoinHandle<()>>>,
}

impl<V> LruCache<V> {
    pub fn new(config: CacheConfig) -> Self {
        Self {
            inner: Arc::new(Mutex::new(Inner {
                nodes: Vec::new(),
                free: Vec::new(),
                map: HashMap::new(),
                head: None,
                tail: None,
                current_memory: 0,
                config,
                stats: Stats::default(),
            })),
            eviction_task: Mutex::new(None),
        }
    }

    pub fn get(&self, key: &str) -> Option<V>
    where
        V: Clone,
    {
        let mut inner = self.inner.lock().expect("poisoned");
        let idx = match inner.map.get(key).copied() {
            Some(i) => i,
            None => {
                inner.stats.misses += 1;
                return None;
            }
        };
        let now = Instant::now();
        let expired = inner.nodes[idx].as_ref().expect("node").expires_at < now;
        if expired {
            inner.remove_idx(idx, EvictReason::Expired);
            inner.stats.misses += 1;
            return None;
        }
        let value = {
            let node = inner.nodes[idx].as_mut().expect("node");
            node.last_accessed = now;
            node.access_count += 1;
            node.value.clone()
        };
        inner.move_to_front(idx);
        inner.stats.hits += 1;
        Some(value)
    }

    /// Non-cloning peek: borrows the value via callback.
    pub fn peek_with<R>(&self, key: &str, f: impl FnOnce(&V) -> R) -> Option<R> {
        let inner = self.inner.lock().expect("poisoned");
        let idx = inner.map.get(key).copied()?;
        let node = inner.nodes[idx].as_ref()?;
        if node.expires_at < Instant::now() {
            return None;
        }
        Some(f(&node.value))
    }

    pub fn put(&self, key: &str, value: V, ttl: Option<Duration>, size: Option<usize>) {
        let mut inner = self.inner.lock().expect("poisoned");
        let size = size.unwrap_or_else(|| std::mem::size_of::<V>());
        let ttl = ttl.unwrap_or(inner.config.default_ttl);
        let now = Instant::now();
        let expires_at = now + ttl;

        if let Some(idx) = inner.map.get(key).copied() {
            let old_size = inner.nodes[idx].as_ref().expect("node").size;
            inner.current_memory = inner.current_memory.saturating_sub(old_size);
            {
                let node = inner.nodes[idx].as_mut().expect("node");
                node.value = value;
                node.size = size;
                node.expires_at = expires_at;
                node.last_accessed = now;
            }
            inner.current_memory += size;
            inner.move_to_front(idx);
            return;
        }

        while inner.current_memory + size > inner.config.max_memory_bytes
            && inner.tail.is_some()
        {
            inner.evict_lru(EvictReason::Memory);
        }
        while inner.map.len() >= inner.config.max_entries && inner.tail.is_some() {
            inner.evict_lru(EvictReason::Lru);
        }

        let key_arc: Arc<str> = Arc::from(key);
        let node = Node {
            key: Arc::clone(&key_arc),
            value,
            expires_at,
            size,
            last_accessed: now,
            access_count: 0,
            prev: None,
            next: None,
        };
        let idx = inner.alloc_node(node);
        inner.map.insert(key_arc, idx);
        inner.current_memory += size;
        inner.push_front(idx);
    }

    pub fn delete(&self, key: &str) -> bool {
        let mut inner = self.inner.lock().expect("poisoned");
        if let Some(idx) = inner.map.get(key).copied() {
            inner.remove_idx(idx, EvictReason::Lru);
            true
        } else {
            false
        }
    }

    pub fn has(&self, key: &str) -> bool {
        let mut inner = self.inner.lock().expect("poisoned");
        let idx = match inner.map.get(key).copied() {
            Some(i) => i,
            None => return false,
        };
        if inner.nodes[idx].as_ref().expect("node").expires_at < Instant::now() {
            inner.remove_idx(idx, EvictReason::Expired);
            return false;
        }
        true
    }

    pub fn len(&self) -> usize {
        self.inner.lock().expect("poisoned").map.len()
    }

    pub fn is_empty(&self) -> bool {
        self.len() == 0
    }

    pub fn memory_usage(&self) -> usize {
        self.inner.lock().expect("poisoned").current_memory
    }

    pub fn stats(&self) -> StatsSnapshot {
        let inner = self.inner.lock().expect("poisoned");
        StatsSnapshot {
            hits: inner.stats.hits,
            misses: inner.stats.misses,
            evictions: inner.stats.evictions,
            expirations: inner.stats.expirations,
            size: inner.map.len(),
            memory: inner.current_memory,
        }
    }

    pub fn clear(&self) {
        let mut inner = self.inner.lock().expect("poisoned");
        while let Some(t) = inner.tail {
            inner.remove_idx(t, EvictReason::Lru);
        }
    }

    pub fn keys(&self) -> Vec<String> {
        let inner = self.inner.lock().expect("poisoned");
        let mut out = Vec::with_capacity(inner.map.len());
        let mut cur = inner.head;
        while let Some(i) = cur {
            let n = inner.nodes[i].as_ref().expect("node");
            out.push(n.key.as_ref().to_owned());
            cur = n.next;
        }
        out
    }
}

